function avatarSVG(look=state.avatar){return chibiSVG(look)}
function animalSVG(look){return chibiSVG(look)}
let avatarRenderCount=0;
function softColor(hex,mix){const base=/^#[0-9a-f]{6}$/i.test(hex)?hex:'#b9d5e7',target=mix>=0?255:0;return '#'+[1,3,5].map(i=>Math.round(parseInt(base.slice(i,i+2),16)*(1-Math.abs(mix))+target*Math.abs(mix)).toString(16).padStart(2,'0')).join('')}
function chibiSVG(look){const color=slot=>{const id=slot==='outfit'&&look.outfitColor&&look.outfitColor!=='original'?look.outfitColor:look[slot],type=slot==='outfit'&&look.outfitColor&&look.outfitColor!=='original'?'outfitColor':slot;return avatarItems.find(x=>x.slot===type&&x.id===id)?.color||'#e1ead5'};const species=look.species||'human',human=species==='human',panda=species==='panda',fur=!human&&look.furColor&&look.furColor!=='natural'?color('furColor'):({fox:'#e5a071',bear:'#ba8b6c',tiger:'#e5b46f',koala:'#b0b8c5',mouse:'#bdc3d4',redpanda:'#c48368'}[species]||(panda?'#fffdf7':color('skin'))),line='#806a67',hair='#574952',renderId='soft-avatar-'+(++avatarRenderCount),furFill='url(#'+renderId+'-fur)',outfitFill='url(#'+renderId+'-outfit)';let ears='';
if(species==='cat')ears=`<path d="M49 97 45 33Q46 22 57 31l47 42m32 0 47-42q11-9 12 2l-4 64" fill="${furFill}" stroke="${line}" stroke-width="3.5"/><path d="m59 67-3-23 28 25m72 0 28-25-3 23" fill="#f0aeb9"/>`;
if(species==='dog')ears=`<path d="M62 64Q30 48 31 103q-1 52 30 41l20-62m98-18q32-16 31 39 1 52-30 41l-20-62" fill="#ad7e65" stroke="${line}" stroke-width="3.5"/><path d="M43 89q-6 25 5 37m149-37q6 25-5 37" stroke="#d9ae95" stroke-width="6" fill="none" stroke-linecap="round"/>`;
if(species==='rabbit')ears=`<path d="M72 88Q42 9 68 7q23-3 31 72m42 0q8-75 31-72 26 2-4 81" fill="${furFill}" stroke="${line}" stroke-width="3.5"/><path d="M77 63Q60 19 69 18q9-2 19 45m64 0q10-47 19-45 9 1-8 45" fill="#edb1c1"/>`;
if(panda)ears=`<circle cx="62" cy="66" r="28" fill="#4a4350" stroke="${line}" stroke-width="3"/><circle cx="178" cy="66" r="28" fill="#4a4350" stroke="${line}" stroke-width="3"/><circle cx="62" cy="66" r="15" fill="#766173"/><circle cx="178" cy="66" r="15" fill="#766173"/>`;
if(species==='fox'||species==='redpanda')ears=`<path d="M51 98 42 30q-1-9 10-3l52 46m32 0 52-46q11-6 10 3l-9 68" fill="${furFill}" stroke="${line}" stroke-width="3.5"/><path d="m55 68-4-25 31 28m76 0 31-28-4 25" fill="#fff3dd"/>`;
if(species==='bear'||species==='tiger')ears=`<circle cx="62" cy="65" r="26" fill="${furFill}" stroke="${line}" stroke-width="3"/><circle cx="178" cy="65" r="26" fill="${furFill}" stroke="${line}" stroke-width="3"/><circle cx="62" cy="65" r="14" fill="#edbdac"/><circle cx="178" cy="65" r="14" fill="#edbdac"/>`;
if(species==='koala')ears=`<g fill="${furFill}" stroke="${line}" stroke-width="3"><path d="M67 49q-27-17-34 2-21 5-12 24-12 23 8 32 9 23 35 8m109-66q27-17 34 2 21 5 12 24 12 23-8 32-9 23-35 8"/></g><circle cx="45" cy="79" r="19" fill="#e6d7e0"/><circle cx="195" cy="79" r="19" fill="#e6d7e0"/>`;
if(species==='mouse')ears=`<circle cx="57" cy="62" r="33" fill="${furFill}" stroke="${line}" stroke-width="3"/><circle cx="183" cy="62" r="33" fill="${furFill}" stroke="${line}" stroke-width="3"/><circle cx="57" cy="62" r="23" fill="#e8b2c5"/><circle cx="183" cy="62" r="23" fill="#e8b2c5"/>`;
const outfitStyle=avatarItems.find(x=>x.slot==='outfit'&&x.id===look.outfit)?.style||'sweater';const clothes=outfitStyle==='hoodie'?`<path d="M99 186q21-18 42 0l-6 16h-30Z" fill="${outfitFill}"/><path d="M107 193v14m26-14v14" stroke="#fff4e7" stroke-width="3"/><path d="M99 220q21-12 42 0v13H99Z" fill="#ffffff40"/>`:outfitStyle==='jacket'?'<path d="m101 186 19 14 19-14-6 22-13-8-13 8Z" fill="#fff5df"/><path d="M120 200v40M89 218h16m30 0h16" stroke="#fff5df" stroke-width="3"/><circle cx="126" cy="214" r="2" fill="#e4c07a"/><circle cx="126" cy="227" r="2" fill="#e4c07a"/>':outfitStyle==='raincoat'?'<path d="m99 186 21 12 21-12-9 20-12-8-12 8Z" fill="#fff3d1"/><path d="M120 200v40m-28-19h15m26 0h15" stroke="#936c44" stroke-width="2"/><g fill="#fff3d1"><circle cx="125" cy="211" r="3"/><circle cx="125" cy="222" r="3"/><circle cx="125" cy="233" r="3"/></g>':outfitStyle==='overalls'?`<path d="M80 198q40-35 80 0v15H80Z" fill="#fff5e6"/><path d="M94 192v42h52v-42h-11v18h-30v-18Z" fill="${outfitFill}" stroke="${line}" stroke-width="2"/><circle cx="100" cy="209" r="3" fill="#e8c779"/><circle cx="140" cy="209" r="3" fill="#e8c779"/><path d="M111 220h18v11h-18Z" fill="#ffffff50"/>`:outfitStyle==='dress'?`<path d="m87 218-14 27q47 12 94 0l-14-27Z" fill="${outfitFill}" stroke="${line}" stroke-width="2"/><path d="M89 214h62" stroke="#fff3e9" stroke-width="5"/><path d="m120 211-12-7v16l12-7 12 7v-16Z" fill="#fff3e9"/><path d="m103 227-4 17m21-16v18m17-19 4 17" stroke="#ffffff50" stroke-width="2"/>`:outfitStyle==='tee'?'<path d="M100 188q20 18 40 0" stroke="#fff7ed" stroke-width="4" fill="none"/><path d="M107 219q-8-9 2-12 6-12 15-4 12-2 12 8 9 9-5 11h-24Z" fill="#fffdf8"/>':outfitStyle==='sailor'?'<path d="m93 185 27 18 27-18-7 24-20-6-20 6Z" fill="#fff9ed"/><path d="m114 202 6 7 6-7-2 25h-8Z" fill="#d78e9e"/><path d="M93 232h54" stroke="#fff9ed" stroke-width="3"/>':'';
const animalMarkings=species==='fox'||species==='redpanda'?`<path d="M48 126q23 6 30 37-24-4-30-37m144 0q-23 6-30 37 24-4 30-37" fill="#fff2df"/>${species==='redpanda'?'<path d="m65 107 18-17 18 9m74 8-18-17-18 9" stroke="#795247" stroke-width="9" fill="none" stroke-linecap="round"/>':''}`:species==='tiger'?'<g stroke="#7e5846" stroke-width="7" stroke-linecap="round"><path d="m103 55 3 19m14-21v23m17-21-3 19M49 104l14 6m-16 15 16 3m128-24-14 6m16 15-16 3"/></g>':species==='koala'?'<ellipse cx="120" cy="139" rx="12" ry="18" fill="#645866"/>':species==='mouse'?'<path d="m74 147-23-5m23 14-23 5m115-14 23-5m-23 14 23 5" stroke="#8b7987" stroke-width="2"/>':'';
const eye=(x)=>`<g class="avatar-eye"><ellipse cx="${x}" cy="120" rx="13" ry="18" fill="#493b50"/><ellipse cx="${x}" cy="127" rx="11" ry="12" fill="#aa819c"/><ellipse cx="${x}" cy="118" rx="9" ry="14" fill="#48364d"/><ellipse cx="${x-5}" cy="111" rx="6" ry="8" fill="white"/><circle cx="${x+6}" cy="126" r="4" fill="#fff9ed"/><path d="M${x-14} 107q13-13 27-1" stroke="${line}" stroke-width="4" fill="none" stroke-linecap="round"/></g>`;
const humanHair=human?`<path d="M45 106Q33 35 120 37q85-2 75 70-22-2-38-30-5 17-22 26l-2-29q-21 26-48 31l6-23q-19 22-46 24" fill="${hair}" stroke="${line}" stroke-width="3"/><path d="M71 66q18-17 44-18m13 0q20-1 36 13" stroke="#7a5a70" stroke-width="5" stroke-linecap="round" fill="none"/>${look.hair==='curls'?Array.from({length:6},(_,i)=>`<circle cx="${57+i*25}" cy="${66-Math.sin(i/5*Math.PI)*20}" r="19" fill="${hair}" stroke="${line}" stroke-width="2"/>`).join(''):''}`:'';
return `<svg class="chibi-avatar" viewBox="0 0 240 260" role="img" aria-label="Your customized chibi ${human?'explorer':species} avatar"><defs><radialGradient id="${renderId}-fur" cx="32%" cy="24%" r="85%"><stop offset="0" stop-color="${softColor(fur,.4)}"/><stop offset=".55" stop-color="${fur}"/><stop offset="1" stop-color="${softColor(fur,-.2)}"/></radialGradient><linearGradient id="${renderId}-outfit" x1="0" y1="0" x2="1" y2="1"><stop stop-color="${softColor(color('outfit'),.3)}"/><stop offset=".6" stop-color="${color('outfit')}"/><stop offset="1" stop-color="${softColor(color('outfit'),-.2)}"/></linearGradient><radialGradient id="${renderId}-blush"><stop stop-color="#e89b9e" stop-opacity=".65"/><stop offset="1" stop-color="#e89b9e" stop-opacity="0"/></radialGradient></defs><ellipse cx="120" cy="138" rx="116" ry="116" fill="${color('background')}" opacity=".65"/><ellipse cx="110" cy="104" rx="93" ry="85" fill="#fff" opacity=".35"/><g fill="#fff9f1" opacity=".9"><path d="m24 47 3 7 8 3-8 3-3 7-3-7-8-3 8-3Zm185 111 3 6 7 3-7 3-3 7-3-7-7-3 7-3Z"/><circle cx="212" cy="93" r="4"/><circle cx="31" cy="185" r="3"/></g><ellipse class="avatar-shadow" cx="120" cy="248" rx="57" ry="7" fill="${line}" opacity=".12"/><g class="avatar-character"><g stroke="${line}" stroke-width="1.7" stroke-linejoin="round"><ellipse cx="101" cy="241" rx="17" ry="11" fill="#f4e6d6"/><ellipse cx="139" cy="241" rx="17" ry="11" fill="#f4e6d6"/><path d="M83 192q-18 3-22 24-1 13 12 12l19-17" fill="${outfitFill}"/><ellipse cx="68" cy="224" rx="9" ry="8" fill="${furFill}"/><path d="M79 230q-6-43 41-49 47 6 41 49-3 17-41 17t-41-17Z" fill="${outfitFill}"/><path d="M103 185q17 20 34 0" stroke="#fff7ee" stroke-width="6" fill="none"/>${clothes}${human&&look.hair==='bob'?`<path d="M45 102q-4-67 75-67t75 67v82q-18 12-34-4H79q-16 16-34 4Z" fill="${hair}"/>`:''}<g class="avatar-ears">${ears}</g><path d="M43 115q0-66 77-66t77 66q5 69-77 73-82-4-77-73Z" fill="${furFill}"/>${!human&&!panda?'<path d="m108 54 5 16m7-17 1 19m9-17-3 15" stroke="#c29579" stroke-linecap="round"/>':''}</g>${humanHair}${animalMarkings}${panda?'<ellipse cx="86" cy="120" rx="25" ry="31" fill="#564b59" transform="rotate(12 86 120)"/><ellipse cx="154" cy="120" rx="25" ry="31" fill="#564b59" transform="rotate(-12 154 120)"/>':''}${!human?`<g fill="none" stroke="${softColor(fur,.55)}" stroke-width="1.4" stroke-linecap="round" opacity=".65"><path d="m54 116-4 9m7-2-3 9m6-3-1 7m127-20 4 9m-7-2 3 9m-6-3 1 7m-72-73 3-6m5 5 3-5m4 6 4-5"/></g>`:''}${eye(86)}${eye(154)}<ellipse cx="65" cy="143" rx="21" ry="14" fill="url(#${renderId}-blush)"/><ellipse cx="175" cy="143" rx="21" ry="14" fill="url(#${renderId}-blush)"/><g stroke="#fff1ed" stroke-width="2" opacity=".8"><path d="m59 141-2 6m9-5-2 6m105-7-2 6m9-5-2 6"/></g>${human?'<path d="M111 153q9 13 18 0" stroke="#88546a" stroke-width="3" fill="#f3b4c0" stroke-linecap="round"/>':`<ellipse cx="120" cy="153" rx="26" ry="20" fill="#fffaf0" opacity=".75"/><path d="M113 143q7-5 14 0l-7 6Z" fill="${panda||species==='dog'?'#58434d':'#d88b9f'}"/><path d="M120 149v5m-11 0q5 9 11 0 6 9 11 0" stroke="${line}" stroke-width="2.5" fill="none" stroke-linecap="round"/>${species==='cat'||species==='tiger'?'<path d="m73 149-26-4m26 13-24 5m118-14 26-4m-26 13 24 5" stroke="#986e6a" stroke-width="2" stroke-linecap="round"/>':species==='dog'?'<path d="M115 160q5 15 10 0" fill="#ed9baa"/>':species==='rabbit'?'<path d="M116 161h8v9h-8Z" fill="white" stroke="#d8bbaa"/>':''}`}${look.accessory==='glasses'?`<g fill="none" stroke="#795473" stroke-width="3"><circle cx="86" cy="122" r="25"/><circle cx="154" cy="122" r="25"/><path d="M111 121q9-8 18 0m-68-4-17-6m135 6 17-6"/></g>`:look.accessory==='crown'?'<path d="m92 55-6-30 22 15 12-23 12 23 22-15-6 30Z" fill="#f8d77b" stroke="#ae7f4f" stroke-width="2.5"/><circle cx="120" cy="46" r="4" fill="#eda9b4"/>':look.accessory==='star'?'<path d="m146 206 4 7 8 1-6 6 1 8-7-4-7 4 1-8-6-6 8-1Z" fill="#ffe290" stroke="#b78a56" stroke-width="1.5"/>':''}<g class="avatar-wave-arm" stroke="${line}" stroke-width="1.7" stroke-linejoin="round"><path d="M157 192q18 3 22 24 1 13-12 12l-19-17" fill="${outfitFill}"/><ellipse cx="172" cy="224" rx="9" ry="8" fill="${furFill}"/></g></g></svg>`}
function greetAvatar(selector){const svg=$(selector+' svg');if(!svg)return false;toast(avatarName()+' says 你好!');if(window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches)return true;svg.classList.remove('is-greeting');void svg.getBoundingClientRect().width;svg.classList.add('is-greeting');svg.onanimationend=e=>{if(e.animationName==='chibi-wave')svg.classList.remove('is-greeting')};return true}
let avatarPlay={action:'hello',caught:0,catching:false,starX:50,starY:20};
function openAvatarPlay(){avatarPlay={action:'hello',caught:0,catching:false,starX:50,starY:20};renderAvatarPlay();$('#avatar-play-dialog').showModal()}
function playWithAvatar(action){if(!['pet','snack','catch','star'].includes(action))return false;if(action==='catch'){avatarPlay.caught=0;avatarPlay.catching=true;avatarPlay.action='catch'}else if(action==='star'){if(!avatarPlay.catching)return false;avatarPlay.caught++;if(avatarPlay.caught>=5){avatarPlay.catching=false;avatarPlay.action='celebrate'}}else{avatarPlay.catching=false;avatarPlay.action=action}avatarPlay.starX=avatarPlay.caught%2?72:28;avatarPlay.starY=15+Math.round(Math.random()*25);renderAvatarPlay();if(action!=='catch'&&action!=='star')greetAvatar('.playroom-avatar');return true}
function renderAvatarPlay(){const name=esc(avatarName()),messages={hello:'A cozy little break with '+avatarName()+'.',pet:avatarName()+' leans into your gentle pats. ♡',snack:'A tasty treat! '+avatarName()+' is delighted.',catch:'Tap the star to play catch together.',celebrate:'Five stars caught! '+avatarName()+' loved playing with you.'};$('#avatar-play-content').innerHTML=`<div class="modal-top"><span class="eyebrow">AVATAR PLAYROOM</span><button class="close" id="playroom-close" aria-label="Close avatar playroom">×</button></div><h2>Play with ${name}</h2><p>Pet, share a snack, or play a little catch. Everything here is free.</p><div class="playroom-arena action-${avatarPlay.action}"><div class="playroom-cloud cloud-one"></div><div class="playroom-cloud cloud-two"></div><div class="playroom-avatar">${avatarSVG()}</div>${avatarPlay.action==='pet'?'<div class="playroom-hearts" aria-hidden="true">♡ &nbsp; ♥ &nbsp; ♡</div>':avatarPlay.action==='snack'?'<div class="playroom-snack" aria-hidden="true">🍓</div>':''}${avatarPlay.catching?`<button id="catch-star" class="playroom-star" style="left:${avatarPlay.starX}%;top:${avatarPlay.starY}%" aria-label="Catch star ${avatarPlay.caught+1} of 5">⭐</button>`:''}</div><p class="playroom-status" role="status">${esc(messages[avatarPlay.action])}</p><p class="playroom-catch-count">${avatarPlay.catching||avatarPlay.action==='celebrate'?'⭐ '+avatarPlay.caught+' / 5 stars caught':'♡ A happy moment together'}</p><div class="playroom-controls"><button class="secondary" id="pet-avatar">♡ Pet</button><button class="secondary" id="feed-avatar">🍓 Snack</button><button class="primary" id="play-catch">${avatarPlay.action==='celebrate'?'Play again':'⭐ Play catch'}</button></div><p class="quest-help">Play for fun—your points and learning progress stay unchanged.</p>`;$('#playroom-close').onclick=()=>$('#avatar-play-dialog').close();$('#pet-avatar').onclick=()=>playWithAvatar('pet');$('#feed-avatar').onclick=()=>playWithAvatar('snack');$('#play-catch').onclick=()=>playWithAvatar('catch');if(avatarPlay.catching)$('#catch-star').onclick=()=>playWithAvatar('star')}
function avatarName(){return typeof state.avatar.name==='string'&&state.avatar.name.trim()?state.avatar.name.trim():'Mochi'}
function setAvatarName(value){const name=String(value).replace(/[\u0000-\u001f\u007f]/g,'').trim().replace(/\s+/g,' ');if(!name||[...name].length>24)return false;state.avatar.name=name;save();return true}
function showAvatarReaction(correct,target='#answer-reaction'){const mount=$(target);if(!mount)return;const headline=correct?'太棒了！ Great job!':'加油！ You’ve got this!';const name=avatarName();const message=correct?name+' is cheering for you.':name+' believes in you. Every try is a step forward.';mount.hidden=false;mount.innerHTML=`<div class="avatar-response ${correct?'is-correct':'is-encouraging'}"><div class="reaction-scene" aria-hidden="true"><div class="reaction-avatar">${avatarSVG()}</div><span class="reaction-spark spark-one">${correct?'✦':'♥'}</span><span class="reaction-spark spark-two">${correct?'★':'✧'}</span><span class="reaction-spark spark-three">${correct?'✧':'♥'}</span></div><div><strong>${headline}</strong><p>${esc(message)}</p></div></div>`}
function buyAvatarItem(key){const item=avatarItems.find(x=>x.slot+'-'+x.id===key);if(!item)return false;const owned=state.owned.includes(key)||item.price===0;if(!owned&&state.points<item.price){toast('Earn more points from quests or trade XP in the shop.');return false}if(!owned){state.points-=item.price;state.owned.push(key)}state.avatar[item.slot]=item.id;save();updateHeader();return true}
function exchangeXP(){if(!Number.isFinite(state.xp)||state.xp<50)return false;state.xp-=50;state.points+=5;save();updateHeader();return true}
function previewAvatarItem(key){const item=avatarItems.find(x=>x.slot+'-'+x.id===key);if(!item)return false;const owned=state.owned.includes(key)||item.price===0,affordable=owned||state.points>=item.price;const look={...state.avatar,[item.slot]:item.id};$('#try-on-content').innerHTML=`<div class="modal-top"><span class="eyebrow">DRESSING ROOM · TRY IT ON</span><button class="close" id="try-on-close" aria-label="Close try-on preview">×</button></div><div class="try-on-body"><div class="try-on-avatar">${avatarSVG(look)}</div><button class="secondary avatar-greet-button" id="try-greet">See it in motion ♡</button><span class="try-on-badge">Preview only · Not saved</span><h2 id="try-on-title">${esc(item.name)}</h2><p>How does ${esc(avatarName())} look?</p><div class="try-on-price">${owned?(item.price===0?'Free to wear':'Already yours'):item.price+' avatar points'}</div><p class="try-on-balance">Your balance: ${state.points} points${!affordable?' · Earn '+(item.price-state.points)+' more points to buy this.':''}</p><p class="quest-help">Trying on never spends points or changes your saved avatar.</p><div class="try-on-actions"><button class="primary" id="try-on-buy" ${affordable?'':'disabled'}>${owned?'Wear this item':'Buy & wear · '+item.price+' points'}</button><button class="secondary" id="try-on-cancel">Keep my current look</button></div><p id="try-on-status" role="status"></p></div>`;$('#try-greet').onclick=()=>greetAvatar('.try-on-avatar');const dialog=$('#try-on-dialog');$('#try-on-close').onclick=$('#try-on-cancel').onclick=()=>dialog.close();$('#try-on-buy').onclick=()=>{if(!buyAvatarItem(key)){$('#try-on-status').textContent='You do not have enough points yet. Your saved look has not changed.';return}dialog.close();avatarShop();toast(owned?'New look saved!':'Purchased and equipped · −'+item.price+' points')};dialog.showModal();return true}
function avatarShop(){const labels={species:'Choose your companion',...(state.avatar.species==='human'?{skin:'Skin tone',hair:'Hair'}:{furColor:'Fur color'}),outfit:'Clothing style',outfitColor:'Clothing color',accessory:'Accessories',background:'Background'};$('#view').innerHTML=`<span class="eyebrow">A LOOK THAT GROWS WITH YOU</span><h1>Meet your Mandarin explorer.</h1><p class="shop-try-on-note">Tap any item to try it on. Points are only spent when you choose Buy & wear.</p><p>Visit each day for 5 points. Earn 100 points when you first master a level, or 25 points for a perfect replay.</p><div class="avatar-layout"><section class="panel avatar-preview">${avatarSVG()}<button class="secondary avatar-greet-button" id="shop-greet">Play with me ♡</button><h2>${esc(avatarName())}</h2><p>${avatarItems.find(x=>x.slot==='species'&&x.id===state.avatar.species).name}</p><form id="avatar-name-form" class="avatar-name-form"><label for="avatar-name">Name your avatar</label><input id="avatar-name" name="avatarName" value="${esc(state.avatar.name||'')}" placeholder="Mochi" maxlength="48" autocomplete="off" aria-describedby="avatar-name-help avatar-name-status"><small id="avatar-name-help">Choose a name up to 24 characters.</small><button class="secondary" type="submit">Save name</button><p id="avatar-name-status" role="status"></p></form><div class="points-earned">◉ ${state.points} points to spend</div><section class="xp-exchange" aria-labelledby="xp-exchange-title"><h3 id="xp-exchange-title">A little XP, a new look</h3><p><b>${state.xp} XP available</b></p><div class="xp-exchange-rate">50 XP <span>→</span> 5 points</div><button class="secondary" id="exchange-xp" ${state.xp<50?'disabled':''} aria-describedby="xp-exchange-help">Trade 50 XP for 5 points</button><p id="xp-exchange-help">${state.xp<50?`Earn ${50-state.xp} more XP to trade.`:"Trade as often as your XP balance allows."} Trading uses XP from your balance; your daily goal and learning progress stay saved.</p></section><p>Your look and purchases save automatically in this browser. Already completed levels have been credited too.</p><button class="primary" id="earn-more">Learn & earn →</button></section><div>${Object.entries(labels).map(([slot,label])=>`<section class="panel avatar-category"><h3>${label}</h3><div class="avatar-items">${avatarItems.filter(x=>x.slot===slot).map(x=>{const key=x.slot+'-'+x.id,owned=state.owned.includes(key)||x.price===0,equipped=(state.avatar[x.slot]||(x.slot==='outfitColor'?'original':x.slot==='furColor'?'natural':null))===x.id;return `<button data-item="${key}" class="avatar-item ${equipped?'equipped':''}" aria-pressed="${equipped}"><span class="item-swatch" style="background:${x.color||'#e9eddf'}">${x.icon|| (x.color?'':x.id==='crown'?'♛':x.id==='star'?'★':x.id==='glasses'?'◎':x.slot==='hair'?'〰':x.style==='hoodie'?'♧':x.style==='dress'?'୨୧':x.slot==='outfit'?'✧':'—')}</span><b>${x.name}</b><small>${equipped?'✓ Wearing · Preview':owned?'Try on · Owned':`Try on · ${x.price} points`}</small></button>`}).join('')}</div></section>`).join('')}</div></div>`;$('#shop-greet').onclick=()=>openAvatarPlay();$('#exchange-xp').onclick=()=>{if(exchangeXP()){avatarShop();toast('Trade complete! −50 XP · +5 avatar points')}else toast('You need at least 50 XP to trade.')};$('#avatar-name-form').onsubmit=e=>{e.preventDefault();if(!setAvatarName($('#avatar-name').value)){$('#avatar-name-status').textContent='Enter a name between 1 and 24 characters.';return}avatarShop();$('#avatar-name-status').textContent=avatarName()+' is ready to learn with you!'};$('#earn-more').onclick=()=>{tab='learn';render()};document.querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>previewAvatarItem(b.dataset.item))}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});$('#sound').onclick=()=>{audio=!audio;$('#sound').textContent='♫ Audio '+(audio?'on':'off')};$('#lesson').addEventListener('close',()=>{stopWritingCheck();stopLessonRecognition();render()});render();checkDailyBonus();document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')checkDailyBonus()});window.addEventListener('pageshow',()=>checkDailyBonus());
